    private final String guestType;

    // initialization

    OccupiedRoom(String aGuestType) {
        guestType = aGuestType;
    }

    // testing

    @Override
    boolean isAvailable() {
        return false;
    }

    @Override
    boolean isOccupied() {
        return true;
