            return aPriceList.get(guestType);
        }

        return unknownGuestTypeBlock.get();
    }

    @Override
    Integer lossUsingIfAbsentGuestType(Map<String, Integer> aPriceList, Supplier<Integer> unknownGuestTypeBlock) {
        return 0;
    }
}
